import fs from "node:fs";
import path from "node:path";
import prettier from "prettier";
import {
  ArrowFunction,
  ClassDeclaration,
  FileSystemRefreshResult,
  FunctionDeclaration,
  FunctionExpression,
  Node,
  Project,
  SourceFile,
  SyntaxKind,
  TypeAliasDeclaration,
  ts,
} from "ts-morph";
import { reporter } from "./reporter.js";
import { FileChange, RegistryAutomOptions } from "./types.js";

const generatedMarker =
  "// This file is auto-generated by TypeSynth's registry autom.";

type RegistryDeclaration =
  | ReturnType<SourceFile["getInterfaces"]>[number]
  | TypeAliasDeclaration
  | ClassDeclaration;

type RegisteredValue = {
  name: string;
  sourceFile: SourceFile;
  declaration: Node;
};

type RegistryDefinition = {
  name: string;
  declaration: RegistryDeclaration;
  outputPath: string;
};

type FileContribution = {
  values: Map<string, RegisteredValue[]>;
  declaredRegistries: Set<string>;
  warnings: string[];
};

export type RegistryRunStats = {
  mode: "full" | "incremental";
  projectGeneration: number;
  scannedFiles: number;
  renderedOutputs: number;
};

const normalize = (value: string) => value.replace(/\\/g, "/");
const withoutTsExtension = (value: string) =>
  value.replace(/\.d\.ts$/i, "").replace(/\.(tsx?|jsx?)$/i, "");

function jsDocTags(node: Node): Array<{ name: string; comment: string }> {
  const docs = (node as any).getJsDocs?.() ?? [];
  return docs.flatMap((doc: any) =>
    doc.getTags().map((tag: any) => ({
      name: tag.getTagName(),
      comment: (tag.getCommentText?.() ?? "").trim(),
    })),
  );
}

function parseTag(comment: string, tagName: string) {
  const parts = comment.split(/\s+/).filter(Boolean);
  if (parts.length === 0 || parts.length > 2) {
    throw new Error(
      `@${tagName} requires a registry name${tagName === "registry" ? " and an optional output path" : ""}.`,
    );
  }
  return parts;
}

function lowerCamel(value: string) {
  const words = value.match(/[A-Z]+(?=[A-Z][a-z]|$)|[A-Z]?[a-z]+|\d+/g) ?? [
    value,
  ];
  return words
    .map((word, index) =>
      index === 0
        ? word.toLowerCase()
        : word.charAt(0).toUpperCase() + word.slice(1).toLowerCase(),
    )
    .join("");
}

function isInside(root: string, candidate: string) {
  const relative = path.relative(root, candidate);
  return (
    relative === "" ||
    (!relative.startsWith("..") && !path.isAbsolute(relative))
  );
}

function getFilesRecursively(folder: string): string[] {
  return fs.readdirSync(folder, { withFileTypes: true }).flatMap((entry) => {
    const fullPath = path.join(folder, entry.name);
    return entry.isDirectory() ? getFilesRecursively(fullPath) : [fullPath];
  });
}

function resolveOutputPath(
  outputRoot: string,
  registryName: string,
  override?: string,
) {
  const relative = override ?? `${lowerCamel(registryName)}Registry.gen.ts`;
  if (path.isAbsolute(relative) || !relative.toLowerCase().endsWith(".ts")) {
    throw new Error(
      `Registry output "${relative}" must be a relative .ts path.`,
    );
  }
  const resolved = path.resolve(outputRoot, relative);
  if (!isInside(outputRoot, resolved)) {
    throw new Error(
      `Registry output "${relative}" cannot escape ${outputRoot}.`,
    );
  }
  return resolved;
}

function exportedRuntimeValues(sourceFile: SourceFile): RegisteredValue[] {
  const values: RegisteredValue[] = [];
  for (const declaration of [
    ...sourceFile.getFunctions(),
    ...sourceFile.getClasses(),
  ]) {
    const name = declaration.getName();
    if (name && declaration.isExported() && !declaration.isDefaultExport()) {
      values.push({ name, sourceFile, declaration });
    }
  }
  for (const statement of sourceFile.getVariableStatements()) {
    if (!statement.isExported() || statement.isDefaultExport()) continue;
    for (const declaration of statement.getDeclarations()) {
      values.push({ name: declaration.getName(), sourceFile, declaration });
    }
  }
  return values;
}

function functionLike(value: RegisteredValue) {
  if (Node.isFunctionDeclaration(value.declaration)) return value.declaration;
  if (!Node.isVariableDeclaration(value.declaration)) return undefined;
  const initializer = value.declaration.getInitializer();
  return initializer &&
    (Node.isArrowFunction(initializer) ||
      Node.isFunctionExpression(initializer))
    ? initializer
    : undefined;
}

function parameterUsesRegistry(
  fn: FunctionDeclaration | ArrowFunction | FunctionExpression,
  registry: RegistryDefinition,
) {
  if (fn.getParameters().length !== 1) return false;
  const type = fn.getParameters()[0].getType();
  const symbol = type.getAliasSymbol() ?? type.getSymbol();
  return (
    symbol
      ?.getDeclarations()
      .some((declaration) => declaration === registry.declaration) ?? false
  );
}

function moduleSpecifier(
  sourceFile: SourceFile,
  outputPath: string,
  project: Project,
) {
  const sourcePath = withoutTsExtension(sourceFile.getFilePath());
  const options = project.getCompilerOptions();
  const baseUrl = options.baseUrl ? path.resolve(options.baseUrl) : undefined;
  const aliases: Array<{ specifier: string; score: number }> = [];
  if (baseUrl && options.paths) {
    for (const [alias, targets] of Object.entries(options.paths)) {
      for (const target of targets) {
        const absolutePattern = normalize(path.resolve(baseUrl, target));
        const star = absolutePattern.indexOf("*");
        const source = normalize(sourcePath);
        if (star === -1) {
          if (source === withoutTsExtension(absolutePattern)) {
            aliases.push({ specifier: alias, score: absolutePattern.length });
          }
          continue;
        }
        const prefix = absolutePattern.slice(0, star);
        const suffix = withoutTsExtension(absolutePattern.slice(star + 1));
        if (source.startsWith(prefix) && source.endsWith(suffix)) {
          const wildcard = source.slice(
            prefix.length,
            source.length - suffix.length || undefined,
          );
          aliases.push({
            specifier: alias.replace("*", wildcard),
            score: prefix.length + suffix.length,
          });
        }
      }
    }
  }
  if (aliases.length > 0) {
    return aliases.sort((a, b) => b.score - a.score)[0].specifier;
  }
  let relative = normalize(path.relative(path.dirname(outputPath), sourcePath));
  if (!relative.startsWith(".")) relative = `./${relative}`;
  return relative;
}

export class RegistryAutomSession {
  private project: Project;
  private registries = new Map<string, RegistryDefinition>();
  private contributions = new Map<string, FileContribution>();
  private generation = 1;
  private needsRebuild = true;
  readonly tsConfigPath: string;
  outputRoot: string;
  outDir: string | undefined;
  lastRunStats: RegistryRunStats | undefined;

  constructor(
    private readonly configDirectory: string,
    private readonly options: RegistryAutomOptions,
  ) {
    if (
      options.debounceMs !== undefined &&
      (!Number.isFinite(options.debounceMs) || options.debounceMs < 0)
    ) {
      throw new Error(
        "Registry autom debounceMs must be a non-negative number.",
      );
    }
    this.tsConfigPath = path.join(configDirectory, "tsconfig.json");
    if (!fs.existsSync(this.tsConfigPath)) {
      throw new Error(`Registry autom requires ${this.tsConfigPath}.`);
    }
    this.project = this.createProject();
    const paths = this.resolveProjectPaths();
    this.outputRoot = paths.outputRoot;
    this.outDir = paths.outDir;
  }

  private createProject() {
    return new Project({ tsConfigFilePath: this.tsConfigPath });
  }

  private resolveProjectPaths() {
    const compilerOptions = this.project.getCompilerOptions();
    const baseUrl = compilerOptions.baseUrl
      ? path.resolve(compilerOptions.baseUrl)
      : this.configDirectory;
    return {
      outputRoot: path.join(baseUrl, "tsynth-gen", "registry"),
      outDir: compilerOptions.outDir
        ? path.resolve(compilerOptions.outDir)
        : undefined,
    };
  }

  private sourceFiles() {
    return this.project
      .getSourceFiles()
      .filter(
        (sourceFile) => !isInside(this.outputRoot, sourceFile.getFilePath()),
      );
  }

  private registryDeclarations(sourceFile: SourceFile) {
    const declarations: RegistryDeclaration[] = [
      ...sourceFile.getInterfaces(),
      ...sourceFile.getTypeAliases(),
      ...sourceFile.getClasses(),
    ];
    return declarations.flatMap((declaration) =>
      jsDocTags(declaration)
        .filter((tag) => tag.name === "registry")
        .map((tag) => ({
          declaration,
          parts: parseTag(tag.comment, "registry"),
        })),
    );
  }

  private discoverRegistries(sourceFiles: SourceFile[]) {
    const registries = new Map<string, RegistryDefinition>();
    for (const sourceFile of sourceFiles) {
      for (const { declaration, parts } of this.registryDeclarations(
        sourceFile,
      )) {
        const [name, output] = parts;
        if (registries.has(name)) {
          throw new Error(`Registry "${name}" is declared more than once.`);
        }
        registries.set(name, {
          name,
          declaration,
          outputPath: resolveOutputPath(this.outputRoot, name, output),
        });
      }
    }
    return registries;
  }

  private annotatedValues(node: Node, runtimeValues: RegisteredValue[]) {
    if (Node.isVariableStatement(node)) {
      return node
        .getDeclarations()
        .map((declaration) =>
          runtimeValues.find((value) => value.declaration === declaration),
        )
        .filter((value): value is RegisteredValue => !!value);
    }
    const value = runtimeValues.find(
      (candidate) => candidate.declaration === node,
    );
    return value ? [value] : [];
  }

  private resolvesToRegistry(node: Node, registry: RegistryDefinition) {
    if (!Node.isIdentifier(node)) return false;
    let symbol = node.getSymbol();
    if (symbol && (symbol.getFlags() & ts.SymbolFlags.Alias) !== 0) {
      symbol = symbol.getAliasedSymbol();
    }
    return (
      symbol
        ?.getDeclarations()
        .some((declaration) => declaration === registry.declaration) ?? false
    );
  }

  private scanSourceFile(sourceFile: SourceFile): FileContribution {
    const runtimeValues = exportedRuntimeValues(sourceFile);
    const values = new Map<string, RegisteredValue[]>();
    const declaredRegistries = new Set(
      this.registryDeclarations(sourceFile).map(({ parts }) => parts[0]),
    );
    const add = (registryName: string, value: RegisteredValue) => {
      const current = values.get(registryName) ?? [];
      if (
        !current.some(
          (candidate) => candidate.declaration === value.declaration,
        )
      ) {
        current.push(value);
      }
      values.set(registryName, current);
    };

    for (const node of [sourceFile, ...sourceFile.getDescendants()]) {
      for (const tag of jsDocTags(node).filter(
        (candidate) => candidate.name === "register",
      )) {
        const [registryName] = parseTag(tag.comment, "register");
        const registry = this.registries.get(registryName);
        if (!registry) {
          throw new Error(
            `@register references unknown registry "${registryName}".`,
          );
        }
        const annotated = this.annotatedValues(node, runtimeValues);
        if (annotated.length === 0) {
          throw new Error(
            `@register ${registryName} at ${sourceFile.getFilePath()}:${node.getStartLineNumber()} requires a top-level named runtime export.`,
          );
        }
        for (const value of annotated) add(registryName, value);
      }
    }

    const validTypeNodes = new Map<string, Node[]>();
    if (!this.options.useManualRegistration) {
      for (const registry of this.registries.values()) {
        for (const value of runtimeValues) {
          const fn = functionLike(value);
          if (fn && parameterUsesRegistry(fn, registry)) {
            add(registry.name, value);
            const typeNode = fn.getParameters()[0].getTypeNode();
            if (typeNode) {
              const nodes = validTypeNodes.get(registry.name) ?? [];
              nodes.push(typeNode);
              validTypeNodes.set(registry.name, nodes);
            }
          }
        }
      }
    }

    const warnings: string[] = [];
    if (!this.options.useManualRegistration) {
      const warned = new Set<string>();
      for (const identifier of sourceFile.getDescendantsOfKind(
        SyntaxKind.Identifier,
      )) {
        if (
          identifier.getFirstAncestor(
            (ancestor) =>
              Node.isImportDeclaration(ancestor) ||
              Node.isExportDeclaration(ancestor),
          )
        ) {
          continue;
        }
        for (const registry of this.registries.values()) {
          if (!this.resolvesToRegistry(identifier, registry)) continue;
          if (
            identifier === registry.declaration.getNameNode() ||
            identifier.getFirstAncestor(
              (ancestor) => ancestor === registry.declaration,
            )
          ) {
            continue;
          }
          if (
            (validTypeNodes.get(registry.name) ?? []).some(
              (typeNode) =>
                identifier === typeNode ||
                identifier.getFirstAncestor(
                  (ancestor) => ancestor === typeNode,
                ),
            )
          ) {
            continue;
          }
          const key = `${registry.name}:${sourceFile.getFilePath()}:${identifier.getStartLineNumber()}`;
          if (warned.has(key)) continue;
          warned.add(key);
          warnings.push(
            `Registry type "${registry.declaration.getName()}" has a non-inferable usage at ${sourceFile.getFilePath()}:${identifier.getStartLineNumber()}. Use @register ${registry.name} or an exported single-argument function.`,
          );
        }
      }
    }
    return { values, declaredRegistries, warnings };
  }

  private valuesFor(registryName: string) {
    const byName = new Map<string, RegisteredValue>();
    for (const contribution of this.contributions.values()) {
      for (const value of contribution.values.get(registryName) ?? []) {
        const existing = byName.get(value.name);
        if (existing && existing.declaration !== value.declaration) {
          throw new Error(
            `Registry "${registryName}" contains duplicate symbol "${value.name}".`,
          );
        }
        byName.set(value.name, value);
      }
    }
    return [...byName.values()];
  }

  private renderOutput(registries: RegistryDefinition[], outputPath: string) {
    const imports = new Map<string, Set<string>>();
    const registryValues = new Map<string, RegisteredValue[]>();
    for (const registry of registries) {
      const values = this.valuesFor(registry.name);
      registryValues.set(registry.name, values);
      for (const value of values) {
        const specifier = moduleSpecifier(
          value.sourceFile,
          outputPath,
          this.project,
        );
        const names = imports.get(specifier) ?? new Set<string>();
        names.add(value.name);
        imports.set(specifier, names);
      }
    }
    const lines = [generatedMarker, ""];
    for (const [specifier, names] of [...imports].sort(([a], [b]) =>
      a.localeCompare(b),
    )) {
      lines.push(
        `import { ${[...names].sort().join(", ")} } from ${JSON.stringify(specifier)};`,
      );
    }
    if (imports.size > 0) lines.push("");
    for (const registry of registries.sort((a, b) =>
      a.name.localeCompare(b.name),
    )) {
      const members = (registryValues.get(registry.name) ?? [])
        .map((value) => ({
          value,
          member: value.name.endsWith(registry.name)
            ? value.name.slice(0, -registry.name.length)
            : value.name,
        }))
        .sort((a, b) => a.member.localeCompare(b.member));
      const seen = new Set<string>();
      for (const { member } of members) {
        if (!member) {
          throw new Error(
            `Registry "${registry.name}" produced an empty member name.`,
          );
        }
        if (seen.has(member)) {
          throw new Error(
            `Registry "${registry.name}" contains duplicate member "${member}".`,
          );
        }
        seen.add(member);
      }
      lines.push(`export enum ${registry.name}Type {`);
      for (const { member } of members) {
        lines.push(`  ${member} = ${JSON.stringify(member)},`);
      }
      lines.push("}", "", `export const ${registry.name}Map = {`);
      for (const { member, value } of members) {
        lines.push(`  [${registry.name}Type.${member}]: ${value.name},`);
      }
      lines.push("} as const;", "");
    }
    return lines.join("\n");
  }

  private outputGroups() {
    const groups = new Map<string, RegistryDefinition[]>();
    for (const registry of this.registries.values()) {
      const group = groups.get(registry.outputPath) ?? [];
      group.push(registry);
      groups.set(registry.outputPath, group);
    }
    return groups;
  }

  private async render(registryNames?: Set<string>) {
    let rendered = 0;
    for (const [outputPath, registries] of this.outputGroups()) {
      if (
        registryNames &&
        !registries.some((registry) => registryNames.has(registry.name))
      ) {
        continue;
      }
      const formatted = await prettier.format(
        this.renderOutput(registries, outputPath),
        { parser: "typescript", filepath: outputPath },
      );
      fs.mkdirSync(path.dirname(outputPath), { recursive: true });
      if (
        !fs.existsSync(outputPath) ||
        fs.readFileSync(outputPath, "utf8") !== formatted
      ) {
        fs.writeFileSync(outputPath, formatted, "utf8");
      }
      rendered++;
    }
    return rendered;
  }

  private cleanStaleOutputs() {
    if (!fs.existsSync(this.outputRoot)) return;
    const expected = new Set(
      [...this.registries.values()].map((registry) =>
        path.resolve(registry.outputPath),
      ),
    );
    for (const file of getFilesRecursively(this.outputRoot)) {
      if (
        file.endsWith(".ts") &&
        !expected.has(path.resolve(file)) &&
        fs.readFileSync(file, "utf8").startsWith(generatedMarker)
      ) {
        fs.unlinkSync(file);
      }
    }
  }

  async rebuild() {
    if (!this.needsRebuild) {
      for (const sourceFile of this.project.getSourceFiles())
        sourceFile.forget();
      this.project = this.createProject();
      this.generation++;
      const paths = this.resolveProjectPaths();
      this.outputRoot = paths.outputRoot;
      this.outDir = paths.outDir;
    }
    const sourceFiles = this.sourceFiles();
    this.registries = this.discoverRegistries(sourceFiles);
    const nextContributions = new Map<string, FileContribution>();
    for (const sourceFile of sourceFiles) {
      const contribution = this.scanSourceFile(sourceFile);
      nextContributions.set(
        path.resolve(sourceFile.getFilePath()),
        contribution,
      );
      for (const warning of contribution.warnings) reporter.warn(warning);
    }
    this.contributions = nextContributions;
    const renderedOutputs = await this.render();
    this.cleanStaleOutputs();
    this.needsRebuild = false;
    this.lastRunStats = {
      mode: "full",
      projectGeneration: this.generation,
      scannedFiles: sourceFiles.length,
      renderedOutputs,
    };
    return this.lastRunStats;
  }

  private referencingFiles(start: SourceFile) {
    const found = new Map<string, SourceFile>();
    const queue = [start];
    while (queue.length > 0) {
      const current = queue.shift()!;
      for (const reference of current.getReferencingSourceFiles()) {
        const key = path.resolve(reference.getFilePath());
        if (found.has(key) || isInside(this.outputRoot, key)) continue;
        found.set(key, reference);
        queue.push(reference);
      }
    }
    return found;
  }

  async applyChanges(changes: FileChange[]) {
    const local = changes.filter((change) => change.source === "file");
    if (
      this.needsRebuild ||
      local.some(
        (change) =>
          change.type !== "change" ||
          path.resolve(this.configDirectory, change.path) === this.tsConfigPath,
      )
    ) {
      this.needsRebuild = false;
      return this.rebuild();
    }

    const impacted = new Map<string, SourceFile>();
    for (const change of local) {
      const absolute = path.resolve(this.configDirectory, change.path);
      const sourceFile = this.project.getSourceFile(absolute);
      const previous = this.contributions.get(absolute);
      if (!sourceFile || (previous?.declaredRegistries.size ?? 0) > 0) {
        return this.rebuild();
      }
      for (const [file, dependent] of this.referencingFiles(sourceFile)) {
        impacted.set(file, dependent);
      }
      const refresh = await sourceFile.refreshFromFileSystem();
      if (refresh === FileSystemRefreshResult.Deleted) return this.rebuild();
      if (this.registryDeclarations(sourceFile).length > 0)
        return this.rebuild();
      impacted.set(absolute, sourceFile);
      for (const [file, dependent] of this.referencingFiles(sourceFile)) {
        impacted.set(file, dependent);
      }
    }

    const affectedRegistries = new Set<string>();
    for (const [file, sourceFile] of impacted) {
      const previous = this.contributions.get(file);
      for (const name of previous?.values.keys() ?? [])
        affectedRegistries.add(name);
      const contribution = this.scanSourceFile(sourceFile);
      for (const name of contribution.values.keys())
        affectedRegistries.add(name);
      const oldWarnings = new Set(previous?.warnings ?? []);
      for (const warning of contribution.warnings) {
        if (!oldWarnings.has(warning)) reporter.warn(warning);
      }
      this.contributions.set(file, contribution);
    }
    const renderedOutputs = await this.render(affectedRegistries);
    this.lastRunStats = {
      mode: "incremental",
      projectGeneration: this.generation,
      scannedFiles: impacted.size,
      renderedOutputs,
    };
    return this.lastRunStats;
  }

  dispose() {
    for (const sourceFile of this.project.getSourceFiles()) sourceFile.forget();
    this.contributions.clear();
    this.registries.clear();
  }
}

export async function runRegistryAutom(
  configDirectory: string,
  options: RegistryAutomOptions,
) {
  const session = new RegistryAutomSession(configDirectory, options);
  try {
    return await session.rebuild();
  } finally {
    session.dispose();
  }
}
